import * as THREE from 'three/webgpu';
import { texture, uv, vec4, mix, uniform } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'journal-card-1-label';
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;

  const map = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const geometry = new THREE.PlaneGeometry(width, height);

  const inkColor = new THREE.Color('#16161d');
  const surfaceColor = new THREE.Color('#0b0b10');

  const gradientMix = uniform(0.35);
  const uvNode = uv();
  const baseTex = texture(map, uvNode);
  const engineeredGradient = mix(
    vec4(surfaceColor.r, surfaceColor.g, surfaceColor.b, 1.0),
    vec4(inkColor.r, inkColor.g, inkColor.b, 1.0),
    uvNode.y
  );

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = mix(baseTex, engineeredGradient, gradientMix);
  material.transparent = false;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'journal-card-1-label-plane';
  group.add(mesh);

  const textMesh = createTextMesh({
    text: 'Journal 1',
    font: 'Lora',
    weight: 400,
    sizeEm: 0.34,
    color: '#e8ecf2',
    atlas: ctx.fontAtlas,
    align: 'left',
    anchor: 'center'
  });

  textMesh.position.set(-width / 2 + 0.25, 0, 0.01);
  group.add(textMesh);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
    group.clear();
  };

  return group;
}
